import { createEffect, onCleanup, onMount, Show } from "solid-js";
import { render } from "solid-js/web";

import { IsControllerActive, IsTouchActive } from "#core/ui-next/services/input.js";

import { AgeTransitionLoadScreen } from "#base/ui-next/screens/age-transition/age-transition-load-screen.jsx";
import { createLoadScreenModel, LoadCurtainClosedEvent } from "#base/ui-next/screens/load-screen/load-screen-model.js";
import { LoadScreen, LoadScreenContext } from "#base/ui-next/screens/load-screen/load-screen.jsx";

/**
 * Bootstrap the load screen in game, this should control game functions indirectly related to the load screen that need to be run in a reactive context.
 */
if (UI.isInGame() || UI.isInLoading()) {
	const model = createLoadScreenModel();
	const isSaveLoad = !Modding.getTransitionInProgress();
	const loadingCurtain = document.getElementById("loading-curtain");

	// Make the curtain transparent immediately for age transitions so the blurred game world
	// shows through from the very first frame, before any SolidJS rendering occurs.
	if (!isSaveLoad) {
		loadingCurtain?.classList.add("age-transition");
	}

	if (model) {
		if (!loadingCurtain) {
			console.error("Unable to render load screen - could not find loading curtain");
		} else {
			let dispose: (() => void) | undefined;
			const handleCurtainClosed = (event: AnimationEvent) => {
				if (event.target != loadingCurtain || !loadingCurtain.classList.contains("curtain-opened")) {
					return;
				}

				loadingCurtain.removeEventListener("animationend", handleCurtainClosed);
				dispose?.();
				dispose = undefined;

				window.dispatchEvent(new LoadCurtainClosedEvent({ closed: true }));
			};

			dispose = render(() => {
				// When we have model data, remove the hourglass
				createEffect(() => {
					if (model.data || UI.getGameLoadingState() == UIGameLoadingState.GameStarted) {
						const hourglassElement = document.getElementById("load-screen-flip-book");
						hourglassElement?.remove();
					}
				});

				// Show and hide the cursor based on controller state
				createEffect(() => {
					if (IsControllerActive() || IsTouchActive()) {
						UI.hideCursor();
					} else {
						UI.showCursor();
					}
				});

				onMount(() => {
					Input.setActiveContext(InputContext.Shell);
				});

				onCleanup(() => {
					loadingCurtain.removeEventListener("animationend", handleCurtainClosed);
					if (!Configuration.getGame().isHotseat) {
						// Hotseat still gets the player curtain after, the world input is not valid
						Input.setActiveContext(InputContext.World);
					}
				});

				return (
					<LoadScreenContext.Provider value={model}>
						<Show
							when={isSaveLoad}
							fallback={<AgeTransitionLoadScreen />}
						>
							<LoadScreen />
						</Show>
					</LoadScreenContext.Provider>
				);
			}, loadingCurtain);

			loadingCurtain.addEventListener("animationend", handleCurtainClosed);
		}
	} else {
		console.error("Unable to render load screen - model could not be created");
	}
}
